async function admin(){if(!me)return authGate();if(!['ops','admin'].includes(me.role)){setView(heading('Organiser access only.','Your account does not have access to the operations console.'));return;}const entity=new URLSearchParams(location.search).get('section')||'booking-requests';const tabs=adminEntities.filter(e=>me.role==='admin'||e==='booking-requests');if(!tabs.includes(entity))throw new Error('This section is not available for your role.');const header=`${heading('The trip desk.','Manage partner content, approved prices and assisted booking requests.','Organiser · Operations')}<div class="tabs">${tabs.map(e=>`<a class="${entity===e?'active':''}" href="/admin?section=${e}">${esc(e.replaceAll('-',' '))}</a>`).join('')}</div>`;
 if(entity==='leads'){setView(`${header}<div class="panel"><h3>Waitlist leads</h3><p>Exports contain personal data. Use them only for the consented pilot and launch updates.</p><div class="actions"><button id="export-leads">Download CSV</button></div></div>`);$('#export-leads').onclick=async()=>{try{const csv=await request('/admin/leads.csv');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv'})),a=document.createElement('a');a.href=url;a.download='plan-it-leads.csv';a.click();URL.revokeObjectURL(url);}catch(e){toast(e.message);}};return;}
 const rows=await request(`/admin/${entity}${entity==='booking-requests'?'?'+new URLSearchParams({q:new URLSearchParams(location.search).get('q')||'',status:new URLSearchParams(location.search).get('status')||''}):''}`);
 if(entity==='booking-requests'){const users=me.role==='admin'?await request('/admin/users'):[me];const status=new URLSearchParams(location.search).get('status')||'';setView(`${header}<form class="filters" id="queue-filter"><label>Search requests<input name="q" value="${esc(new URLSearchParams(location.search).get('q')||'')}" placeholder="Request ID, customer, route or service" maxlength="200"></label><label>Status<select name="status"><option value="">All requests</option>${['Submitted','In review','Confirmed','Completed','Cancelled','Rejected'].map(x=>`<option ${x===status?'selected':''}>${x}</option>`).join('')}</select></label><button type="submit">Filter queue</button></form><p class="hint">Ops target: Submitted → In review within 30 minutes, 8 am–10 pm IST.</p><div id="queue">${rows.filter(b=>!status||b.status===status).map(b=>`<section class="panel"><div class="row"><h3>${esc(b.kind)} · ${rupees(b.total_paise)}</h3><span class="badge">${esc(b.status)}</span></div><p class="hint">${b.id} · ${b.start_date} · ${esc(b.contact)} · ${Math.floor((Date.now()-Date.parse(b.created_at))/60000)} min since submission</p><p>${esc(b.service_context?.title||'')}</p>${rideSummary(b)}${workflowUI.contactActions(b)}${breakdown(b.price_snapshot)}<form class="form queue-update" data-id="${b.id}" data-revision="${b.revision||1}"><div class="form-row"><label>Next status<select name="status"><option value="">Keep ${esc(b.status)}</option>${({Submitted:['In review','Cancelled'],'In review':['Confirmed','Rejected','Cancelled'],Confirmed:['Completed','Cancelled']}[b.status]||[]).map(x=>`<option>${x}</option>`).join('')}</select></label><label>Assign ops owner<select name="ops_owner_id"><option value="">Unassigned</option>${options(users.filter(u=>['ops','admin'].includes(u.role)),b.ops_owner_id)}</select></label></div>${b.kind==='ride'?'<div class="form-row"><label>Driver name<input name="driver_name" maxlength="100"></label><label>Driver phone<input name="driver_phone" type="tel"></label></div><label>Partner ID<input name="ride_partner_id"></label>':''}<label>Ops note<textarea name="note" maxlength="1000"></textarea></label><button type="submit">Save update</button>${message}</form><div class="actions"></div><details><summary>Status audit</summary><ul>${b.history.map(h=>`<li>${esc(h.to_status)} · ${esc(h.at)} · ${esc(h.note)}</li>`).join('')}</ul></details></section>`).join('')||'<div class="empty">No requests in this queue.</div>'}</div>`);wireForm('#queue-filter',async d=>go(`/admin?section=booking-requests&status=${encodeURIComponent(d.status)}&q=${encodeURIComponent(d.q||'')}`));$$('.queue-update').forEach((f,i)=>{f.id=`queue-${i}`;wireForm(`#${f.id}`,async d=>{const payload={expected_revision:Number(f.dataset.revision),note:d.note,ops_owner_id:d.ops_owner_id||null};for(const key of ['status','driver_name','driver_phone','ride_partner_id'])if(d[key])payload[key]=d[key];await request(`/admin/booking-requests/${f.dataset.id}`,{method:'PATCH',body:payload});toast('Request updated.');await render();});});workflowUI.wireContacts();return;}
 if(entity==='audit-log'){setView(`${header}<div class="table-wrap"><table><thead><tr><th>Time</th><th>Editor</th><th>Entity</th><th>Action / change</th></tr></thead><tbody>${rows.toReversed().map(r=>`<tr><td>${esc(r.at)}</td><td>${esc(r.actor_id)}</td><td>${esc(r.entity)}<br>${esc(r.entity_id)}</td><td>${esc(r.action)}<details><summary>Before / after</summary><pre>${esc(JSON.stringify(r.diff,null,2))}</pre></details></td></tr>`).join('')}</tbody></table></div>`);return;}
 const label=k=>({cost_paise:'Partner cost (paise)',margin_value:'Margin (paise or basis points)',platform_fee_paise:'Platform fee (paise)',gst_bps:'GST (basis points)',ref_id:'Catalogue item ID',cancellation_policy_id:'Cancellation policy ID',valid_from:'Valid from',valid_to:'Valid through',min_group:'Minimum group size',max_group:'Maximum group size',processing_charge_paise:'Processing charge (paise)',no_show_charge_paise:'No-show charge (paise)'}[k]||k.replaceAll('_',' '));
 const choices={destination_id:destinations.map(x=>[x.id,x.name]),category:['pack','stay','ride','surcharge'],unit:['per person','per bed per night','per room per night','per unit per night','per trip'],margin_type:['fixed','percent'],type:['hostel','hotel','airbnb'],vehicle_type:['sedan','suv','tempo'],pricing_unit:['per_bed','per_room','per_unit']};
 if(entity==='price-items'){const [policies,packs,rooms,routes]=await Promise.all([request('/admin/cancellation-policies'),request('/admin/packs'),request('/admin/room-types'),request('/admin/routes')]);choices.cancellation_policy_id=policies.map(x=>[x.id,x.name]);choices.ref_id=[...packs,...rooms,...routes].map(x=>[x.id,x.title||x.name||`${x.from_label} → ${x.to_label} (${x.vehicle_type})`]);}
 if(entity==='room-types')choices.stay_id=(await request('/admin/stays')).map(x=>[x.id,x.name]);
 if(entity==='pack-days')choices.pack_id=(await request('/admin/packs')).map(x=>[x.id,x.title]);
 if(entity==='routes')choices.destination_id=[['campus','Campus transfer'],...choices.destination_id];
 const fields=row=>Object.entries(templates[entity]).map(([key,defaultValue])=>{const value=entity==='routes'&&key==='destination_id'&&row[key]===null?'campus':row[key]??defaultValue;if(key==='slabs')return `<fieldset><legend>Refund slabs</legend>${value.map((v,i)=>`<div class="form-row"><label>Hours before start<input type="number" min="0" name="slab_hours_${i}" value="${v.hours_before}" required></label><label>Refund %<input type="number" min="0" max="100" name="slab_refund_${i}" value="${v.refund_percent}" required></label></div>`).join('')}</fieldset>`;if(typeof defaultValue==='boolean')return `<label class="check"><input type="checkbox" name="${key}" ${value?'checked':''}>${esc(label(key))}</label>`;if(choices[key])return `<label>${esc(label(key))}<select name="${key}" required><option value="" disabled ${value?'':'selected'}>Choose an option</option>${choices[key].map(c=>{const [v,l]=Array.isArray(c)?c:[c,c];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`;}).join('')}</select></label>`;if(Array.isArray(defaultValue))return `<label>${esc(label(key))} (one per line)<textarea name="${key}">${esc(value.join('\n'))}</textarea></label>`;if(typeof defaultValue==='number'||defaultValue===null)return `<label>${esc(label(key))}<input type="number" name="${key}" min="0" step="${key==='distance_km'?'0.1':'1'}" value="${esc(value??'')}" ${defaultValue===null?'':'required'}></label>`;if(['description','extras','address'].includes(key))return `<label>${esc(label(key))}<textarea name="${key}" required>${esc(value)}</textarea></label>`;return `<label>${esc(label(key))}<input name="${key}" ${key.startsWith('valid_')?'type="date"':''} value="${esc(value)}" required></label>`;}).join('');
 setView(`${header}${entity==='price-items'?'<div class="notice">Money is stored in paise (₹1 = 100 paise). Percent margins and GST use basis points (100 = 1%). Price edits require a recent phone OTP. Every change is audited.</div>':''}${entity==='cancellation-policies'?'<div class="notice">Enter refund slabs approved by the organisers. The initial zero values are not approved commercial terms.</div>':''}<div class="admin-grid"><div class="panel"><div class="row"><h3>${esc(entity.replaceAll('-',' '))}</h3><button class="secondary small" id="new-record">New record</button></div><ul class="list">${rows.map(r=>`<li><div class="row"><div><strong>${esc(r.title||r.name||r.to_label||r.ref_id||r.id)}</strong><p class="hint">${esc(r.id)} · ${r.active===false?'Inactive':'Active'}</p>${entity==='price-items'?price({unit:r.unit,total_paise:r.sell_paise}):''}</div><button class="secondary small edit-record" data-id="${r.id}">Edit</button></div></li>`).join('')||'<li>No records yet.</li>'}</ul></div><aside class="panel"><h3 id="editor-title">New record</h3><p class="hint">Partner publication and pricing are separate approvals.</p><form id="record-form" class="form"><div id="editor-fields" class="form">${fields(templates[entity])}</div><button type="submit">Save record</button><button type="button" class="danger" id="delete-record" hidden>Deactivate record</button>${message}</form></aside></div>`);let editing=null;const editor=$('#record-form');$('#new-record').onclick=()=>{editing=null;$('#editor-title').textContent='New record';$('#editor-fields').innerHTML=fields(templates[entity]);$('#delete-record').hidden=true;};$$('.edit-record').forEach(b=>b.onclick=()=>{const row=rows.find(r=>r.id===b.dataset.id);editing=row.id;$('#editor-title').textContent='Edit record';$('#editor-fields').innerHTML=fields(row);$('#delete-record').hidden=false;editor.scrollIntoView({behavior:'smooth',block:'center'});});wireForm('#record-form',async d=>{const body={};for(const [key,value]of Object.entries(templates[entity])){if(key==='slabs'){body.slabs=Object.keys(d).filter(k=>k.startsWith('slab_hours_')).map(k=>({hours_before:Number(d[k]),refund_percent:Number(d[k.replace('hours','refund')])}));}else if(typeof value==='boolean')body[key]=d[key]==='on';else if(typeof value==='number'||value===null)body[key]=d[key]===''&&value===null?null:Number(d[key]);else if(Array.isArray(value))body[key]=d[key].split('\n').map(s=>s.trim()).filter(Boolean);else body[key]=d[key];}if(entity==='routes'&&body.destination_id==='campus')body.destination_id=null;if(entity==='price-items'&&body.active&&body.cost_paise===0&&body.margin_value===0)throw new Error('Enter an approved price before activating this item.');await request(`/admin/${entity}${editing?'/'+editing:''}`,{method:editing?'PATCH':'POST',body});toast('Saved. Catalogue changes are live.');await render();});$('#delete-record').onclick=async()=>{try{await request(`/admin/${entity}/${editing}`,{method:'DELETE',body:{}});toast('Record deactivated.');await render();}catch(e){toast(e.message);}};
}
function about(){setView(`${heading('Born in Bihta. Built for the break.','PLAN-IT is a student-led Innovation & Entrepreneurship project at IIT Patna. We’re building around student budgets, shared plans and the ride out of campus.')}<div class="two-col"><section class="panel"><h2>A little less coordination.<br>A lot more going.</h2><p>The organisers bring trip planning, partner requests and shared expenses into one place. The pilot starts with Ayodhya, Bodh Gaya and Rajgir, with IIT Patna in Bihta as our origin.</p><p class="intro">In this first version, we confirm bookings with partners ourselves. The mobile app is coming soon.</p></section><section class="panel"><h2>Talk to the trip desk.</h2><p>Contact Aryan at the existing PLAN-IT WhatsApp number for assisted booking enquiries, support and privacy requests.</p><p><a href="tel:+918789686217">+91 87896 86217</a></p><div class="actions">${whatsapp('Hi, I’d like help planning a trip.')}</div><p class="micro">Ops response target: 30 minutes, 8 am–10 pm IST. An official support email is awaiting confirmation from the organisers.</p></section></div>`);}
function legal(path){const privacy=path==='/privacy',cancel=path==='/cancellation';setView(`<article class="legal">${heading(privacy?'Your details, with a purpose.':cancel?'Before plans change.':'A few things before you go.','Pilot policy · the organisers')}<div class="notice">Pilot policy information. The organisers must approve final commercial and legal terms before accepting live bookings.</div>${privacy?'<h2>What we collect</h2><p>We store account details, trip participation, booking requests, shared expenses and consented waitlist details. Waitlist details include your name, phone or email, college, campaign source and signup time. We use them to operate trips and send the launch or pilot updates you request.</p><h2>Your control</h2><p>Contact the organisers on WhatsApp to request access, correction, deletion or withdrawal of waitlist consent. Do not add sensitive information to trip notes. Trip members can see shared expenses; a current invite link allows a guest to view the trip board. Only the trip owner can rotate the invite to revoke it.</p><h2>Service providers and retention</h2><p>Production uses Supabase for account verification and PostgreSQL for data. Turnstile verifies public forms. Approved partners receive only the booking details needed to fulfil your request. We collect no card data. The organisers must set and publish a retention schedule before live operation.</p>':cancel?'<h2>Terms before commitment</h2><p>Every bookable item needs an approved cancellation policy. The quote and booking request preserve the policy shown to you. Refunds use the policy slab at the cancellation time, less its processing and no-show charges. The start of the trip day is midnight IST.</p><h2>No assumed refunds</h2><p>There is no universal refund percentage during the pilot. Where a price or policy is missing, booking is disabled. Online payments are not available; refunds cannot exceed the amount actually paid and recorded.</p>':'<h2>Assisted booking</h2><p>Submitting a request does not guarantee availability. The organisers check partner availability and updates your request from Submitted to In review, then Confirmed or Rejected. All prices are in INR and include the tax and fees shown in the quote.</p><h2>Pilot scope</h2><p>Launch destinations are Ayodhya, Bodh Gaya and Rajgir. Tickets and online payments are planned for Phase 2. No live inventory or driver tracking is provided. Use the app responsibly and share invite links only with people you trust.</p>'}<div class="actions">${whatsapp('Hi, I have a question about your pilot policies.')}</div></article>`);}
async function render(){const path=location.pathname;try{document.title=({'/packs':'Travel packs','/stays':'Budget stays','/rides':'Easy rides','/account':'My trips','/admin':'Organiser console','/about':'About PLAN-IT'}[path]||'Campus travel, together')+' · PLAN-IT';if(path==='/')return await home();if(path==='/packs')return await listing('pack');if(path.startsWith('/packs/'))return await detail('pack',path.split('/')[2]);if(path==='/stays')return await listing('stay');if(path.startsWith('/stays/'))return await detail('stay',path.split('/')[2]);if(path==='/rides')return await rides();if(path==='/trips/new')return await newTrip();const m=path.match(/^\/trips\/([^/]+)(\/split)?$/);if(m)return await tripPage(m[1],!!m[2]);const edit=path.match(/^\/booking-requests\/([^/]+)\/edit$/);if(edit)return await workflowUI.editBooking(edit[1]);if(path==='/notifications')return await workflowUI.notifications();if(path==='/account')return await account();if(path==='/admin')return await admin();if(path==='/about')return about();if(['/privacy','/legal/terms','/cancellation'].includes(path))return legal(path);if(path==='/tickets'){setView(`${heading('Tickets are on the way.','Train, bus and flight booking assistance arrives in Phase 2. Assistance fees will be shown separately; train services require compliance approval.')}<div class="notice">Ticket requests are not open yet. No ticket purchase or payment is available.</div><a class="button secondary" href="/packs">Explore travel packs ↗</a>`);return;}if(path==='/auth/callback'){const code=new URLSearchParams(location.search).get('code'),verifier=sessionStorage.getItem('oauth-verifier');if(!code||!verifier)throw new Error('Sign-in session expired. Please try again.');auth=await supabase('/token?grant_type=pkce',{auth_code:code,code_verifier:verifier});sessionStorage.removeItem('oauth-verifier');sessionStorage.setItem('plan-it-auth',JSON.stringify(auth));await loadMe();go('/account');return;}setView(`${heading('This stop isn’t on the map.','The page may have moved, or the link is incomplete.')}<a class="button" href="/">Back to PLAN-IT ↗</a>`);}catch(e){setView(`${heading('We couldn’t load this plan.',e.message)}<div class="actions"><button id="retry-page">Try again</button><a class="button secondary" href="/account">My trips</a></div>`);$('#retry-page').onclick=()=>void render();}}
document.addEventListener('click',e=>{const a=e.target.closest('a');if(!a||a.target||a.hasAttribute('download')||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;const url=new URL(a.href);if(url.origin===location.origin&&!url.hash&&!a.pathname.startsWith('/api/')){e.preventDefault();go(url.pathname+url.search);}});window.addEventListener('popstate',()=>void render());
async function boot(){try{config=await request('/config');destinations=await request('/destinations');for(const template of Object.values(templates))if(template.destination_id&&template.destination_id!=='campus')template.destination_id=destinations.find(d=>d.slug===template.destination_id)?.id||destinations[0]?.id;await loadMe();if(config.demo){$('#demo-banner').hidden=false;$('#demo-banner').innerHTML=`<span>LOCAL DEMO · Sample catalogue · No live bookings or messages</span><label>Preview as <select id="demo-persona">${['student','friend','ops','admin'].map(x=>`<option value="${x}" ${(sessionStorage.getItem('plan-it-persona')||'student')===x?'selected':''}>${x}</option>`).join('')}</select></label>`;$('#demo-persona').onchange=async e=>{sessionStorage.setItem('plan-it-persona',e.target.value);await loadMe();await workflowUI.refreshNotifications();await render();};}await render();await workflowUI.refreshNotifications();if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});}catch(e){setView(`${heading('The trip desk is getting ready.',e.message)}<p>Check your service configuration or start the labelled local demo. <a href="/about">Contact the organisers</a></p>`);}}
const workflowUI=createWorkflowUI({$,$$,request,esc,heading,message,options,wireForm,rupees,breakdown,getMe:()=>me,getTrips:()=>myTrips,render,go,toast,today,tomorrow,authGate,setView,loadMe});
setInterval(()=>{if(!document.hidden)void workflowUI.refreshNotifications();},15000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)void workflowUI.refreshNotifications();});
